(() => {
  'use strict';
  const questions=window.AZ104_QUESTIONS, core=window.AZ104_CORE;
  const byId=new Map(questions.map(q=>[q.id,q]));
  const domains=['Identidades e governança','Armazenamento','Computação','Redes','Monitoramento e backup'];
  const domainIcons=['shield','storage','compute','network','chart'];
  const storageKey='az104-study-draft-v2';
  let state=core.createDraft(questions),storageWarning='',menuOpen=false,dialogAction=null,dialogReturnFocus=null,toastTimer;
  try{const saved=sessionStorage.getItem(storageKey);if(saved)state=core.sanitize(JSON.parse(saved),questions);}
  catch(_){storageWarning='Não foi possível recuperar o treino nesta aba. Você pode começar uma nova sessão.';}
  const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icons={
    book:'<path d="M12 5v15M12 5C9 3 5 3 3 4v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-2-1-6-1-9 1Z"/>',
    grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    check:'<path d="m5 12 4 4L19 6"/>',cross:'<path d="m6 6 12 12M6 18 18 6"/>',
    target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
    chart:'<path d="M4 3v17h17M8 15V9m5 6V5m5 10v-4"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',
    storage:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 4 18 4 18 0V5M3 12c0 4 18 4 18 0"/>',
    compute:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M12 16v5m-4 0h8"/>',
    network:'<rect x="8" y="2" width="8" height="6" rx="1"/><rect x="2" y="16" width="6" height="6" rx="1"/><rect x="16" y="16" width="6" height="6" rx="1"/><path d="M12 8v4M5 16v-4h14v4"/>',
    bulb:'<path d="M8 16C1 9 7 1 12 3c8 0 9 8 4 13l-1 3H9Zm1 6h6"/>',
    bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',link:'<path d="M14 3h7v7m0-7L10 14M10 3H4v17h17v-6"/>',
    file:'<path d="M14 2H5v20h14V7Zm0 0v5h5M8 12h8m-8 4h8"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 14-2l1 6M4 12l1 6a8 8 0 0 0 14-2"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
  const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
  function save(){try{sessionStorage.setItem(storageKey,JSON.stringify(state));}catch(_){storageWarning='O navegador não permitiu salvar esta sessão. Mantenha a aba aberta para continuar seu treino.';}}
  const list=ids=>ids.map(id=>byId.get(id)).filter(Boolean);
  const practiceDomain=()=>questions.filter(q=>state.practice.domain<0||q.domain===state.practice.domain);
  const session=()=>['exam','exam-review'].includes(state.view)?state.exam:state.practice;
  const current=()=>['practice','exam','exam-review'].includes(state.view)&&session()?byId.get(session().ids[session().index]):null;
  function getAnswer(q,active=session()){if(!active.answers[q.id])active.answers[q.id]=core.newAnswer();return active.answers[q.id];}
  const button=(label,action,value,className='',disabled=false)=>`<button type="button" class="btn ${className}" data-action="${action}" ${value!==undefined?`data-value="${escape(value)}"`:''} ${disabled?'disabled':''}>${label}</button>`;
  function statsBoxes(s,exam=false){return `<div class="stats-strip"><div class="stat-box"><div class="stat-icon">${icon('book')}</div><div><div class="stat-value">${exam?s.answered:s.evaluated}<span> / ${s.total}</span></div><div class="stat-label">${exam?'Respostas selecionadas':'Questões respondidas'}</div></div></div><div class="stat-box"><div class="stat-icon teal">${icon(exam?'clock':'target')}</div><div><div class="stat-value">${exam?s.unanswered:s.accuracy===null?'—':s.accuracy+'%'}</div><div class="stat-label">${exam?'Questões em branco':'Taxa de acerto'}</div></div></div><div class="stat-box"><div class="stat-icon purple">${icon(exam?'shield':'check')}</div><div><div class="stat-value">${exam?'Ao final':s.correct}</div><div class="stat-label">${exam?'Correção do simulado':'Respostas corretas'}</div></div></div></div>`;}
  function heading(title,subtitle,tabs=false){const exam=state.view.startsWith('exam');return `<div class="page-heading"><div><p class="eyebrow">Preparação AZ-104</p><h1 tabindex="-1">${title}</h1><p>${subtitle}</p></div>${tabs?`<div class="mode-tabs" role="group" aria-label="Modo de estudo"><button class="mode-tab ${!exam?'active':''}" aria-pressed="${!exam}" data-action="view" data-value="practice">${icon('book')}Treino</button><button class="mode-tab ${exam?'active':''}" aria-pressed="${exam}" data-action="exam-open">${icon('grid')}Simulado</button></div>`:'<span class="pill">Sessão atual</span>'}</div>`;}
  function navItem(label,symbol,action,value,active,count){return `<button class="nav-item ${active?'active':''}" ${active?'aria-current="page"':''} data-action="${action}" ${value!==undefined?`data-value="${escape(value)}"`:''}>${icon(symbol)}<span>${label}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</button>`;}
  function shell(content){const active=state.view==='practice';const crumb={practice:'Prática',progress:'Desempenho',materials:'Materiais','exam-intro':'Simulado',exam:'Simulado','exam-result':'Resultado','exam-review':'Revisão'}[state.view];return `<div class="shell"><aside class="sidebar ${menuOpen?'open':''}" id="navigation"><a class="brand" href="#main" data-action="view" data-value="practice"><span class="brand-symbol">AZ</span><span><strong>AZ-104 Study</strong><small>Azure Administrator</small></span></a><nav aria-label="Estudo"><p class="nav-label">Seu espaço de estudo</p>${navItem('Praticar questões','book','domain',-1,active&&state.practice.domain<0,50)}${navItem('Meu desempenho','chart','view','progress',state.view==='progress')}<div class="nav-divider"></div><p class="nav-label">Áreas de conhecimento</p>${domains.map((d,i)=>navItem(d,domainIcons[i],'domain',i,active&&state.practice.domain===i,10)).join('')}<div class="nav-divider"></div>${navItem('Materiais de estudo','file','view','materials',state.view==='materials')}</nav><div class="sidebar-bottom"><strong>Um conceito de cada vez.</strong><p>Responda, confira a explicação e volte aos temas que precisam de atenção.</p></div></aside><div class="workspace"><header class="topbar"><button class="menu-button" data-action="menu" aria-label="${menuOpen?'Fechar':'Abrir'} menu" aria-expanded="${menuOpen}" aria-controls="navigation">${icon('menu')}</button><span class="mobile-brand">AZ-104 Study</span><div class="breadcrumb">Azure Administrator <span>/</span><strong>${crumb}</strong></div><div class="header-right"><span class="session-label">${icon('clock')} Progresso nesta aba</span><span class="avatar" aria-hidden="true">AZ</span></div></header><main class="page" id="main">${storageWarning?`<div class="save-notice" role="status">${escape(storageWarning)}</div>`:''}${content}<footer class="page-footer"><span>Prática independente · 50 questões, 10 por área</span><a href="#main" data-action="view" data-value="materials">Fontes e metodologia</a></footer></main></div></div>`;}
  function questionMap(active,review=false){const s=core.summarize(list(active.ids),active.answers,review),exam=active===state.exam;return `<section class="right-card"><h2>${exam?'Mapa do simulado':'Seu caminho'}</h2><p>${review?'Escolha uma questão para conferir a explicação.':exam?'Navegue livremente e revise antes de finalizar.':state.practice.filter!=='all'?'Sua seleção de questões para revisar.':state.practice.domain<0?'50 questões em cinco áreas.':'10 questões nesta área.'}</p><div class="progress-head"><span>${exam?'Respostas selecionadas':'Progresso da prática'}</span><strong>${exam?s.answered:s.evaluated}/${s.total}</strong></div><div class="progress-track" role="progressbar" aria-label="${exam?'Respostas selecionadas':'Questões conferidas'}" aria-valuemin="0" aria-valuemax="${s.total}" aria-valuenow="${exam?s.answered:s.evaluated}"><div class="progress-fill" style="width:${s.total?(exam?s.answered:s.evaluated)*100/s.total:0}%"></div></div><div class="question-map ${active.ids.length>10?'all-map':''}">${active.ids.map((id,i)=>{const q=byId.get(id),a=active.answers[id];let status='',label='não respondida';if(review||(!exam&&a?.checked)){status=a?.selected===q.answer?'correct':'incorrect';label=a?.selected===q.answer?'correta':Number.isInteger(a?.selected)?'incorreta':'em branco';}else if(exam&&Number.isInteger(a?.selected)){status='answered';label='respondida';}const marked=state.marked.includes(id);return `<button class="map-cell ${status} ${i===active.index?'current':''} ${marked?'marked':''}" data-action="jump" data-value="${i}" aria-label="Questão ${i+1}, ${label}${marked?', marcada':''}" ${i===active.index?'aria-current="step"':''}>${i+1}</button>`;}).join('')}</div><div class="map-legend">${exam&&!review?'<span><i class="legend-swatch" style="background:#a9c9f7"></i>Respondida</span>':'<span><i class="legend-swatch"></i>Correta</span><span><i class="legend-swatch error"></i>Incorreta</span>'}<span><i class="legend-swatch mark"></i>Marcada</span></div>${exam&&!review?`<div style="margin-top:18px">${button('Finalizar simulado','finish-exam',undefined,'primary')}<p style="margin:12px 0 0">A correção aparece ao finalizar.</p></div>`:''}</section>`;}
  function questionPanel(active,review=false){const q=byId.get(active.ids[active.index]);if(!q)return emptyState();const a=getAnswer(q,active),exam=active===state.exam,revealed=review||(!exam&&a.checked),marked=state.marked.includes(q.id),correctLetter='ABCD'[a.order.indexOf(q.answer)],correct=a.selected===q.answer;return `<section class="question-card" aria-label="Questão atual"><div class="question-top"><div class="question-meta"><span class="domain-tag">${domains[q.domain]}</span><span class="question-number">Questão ${active.index+1} de ${active.ids.length}</span></div><button class="bookmark ${marked?'active':''}" data-action="bookmark" aria-label="${marked?'Desmarcar':'Marcar'} questão para revisão" aria-pressed="${marked}">${icon('bookmark')}</button></div><div class="question-body"><p class="concept">${escape(q.concept)}</p><h2 class="question-text" tabindex="-1" id="question-label">${escape(q.prompt)}</h2><div class="answers" role="radiogroup" aria-labelledby="question-label">${a.order.map((originalIndex,i)=>{const selected=a.selected===originalIndex,isCorrect=revealed&&q.answer===originalIndex,isIncorrect=revealed&&selected&&!isCorrect;return `<button type="button" role="radio" aria-checked="${selected}" ${revealed?'disabled':''} class="answer ${selected?'selected':''} ${isCorrect?'correct':''} ${isIncorrect?'incorrect':''}" data-action="select" data-value="${originalIndex}" tabindex="${a.selected!==null?selected?0:-1:i===0?0:-1}"><span class="answer-letter">${'ABCD'[i]}</span><span class="answer-text">${escape(q.options[originalIndex])}${isCorrect?'<span class="sr-only">, resposta correta</span>':''}${isIncorrect?'<span class="sr-only">, resposta incorreta</span>':''}</span>${isCorrect||isIncorrect?`<span class="answer-symbol">${icon(isCorrect?'check':'cross')}</span>`:''}</button>`;}).join('')}</div>${revealed?`<div class="feedback ${correct?'':'error'}" role="status"><h3 tabindex="-1" id="feedback-title">${icon(correct?'check':'bulb')}${correct?'Resposta correta. Muito bem!':Number.isInteger(a.selected)?'Vamos entender esse conceito':'Esta questão ficou em branco'}</h3><p><strong>Resposta ${correctLetter}: ${escape(q.options[q.answer])}.</strong> ${escape(q.explanation)}</p><a class="reference" href="${escape(q.reference)}" target="_blank" rel="noopener noreferrer">Conferir no Microsoft Learn ${icon('link')}</a>${!exam?`<div style="margin-top:12px">${button('Tentar novamente','retry',undefined,'text')}</div>`:''}</div>`:''}<div class="helper-line">${icon('target')}${exam&&!review?'Você pode mudar sua resposta antes de finalizar.':revealed?'Conecte a decisão ao conceito, além da letra da resposta.':'Selecione uma alternativa e confira a explicação.'}</div></div><div class="question-actions"><div>${button('Anterior','previous',undefined,'',active.index===0)}</div><div>${!exam&&!revealed?button('Pular','next',undefined,'text',active.index===active.ids.length-1)+button('Conferir resposta','check',undefined,'primary',a.selected===null):active.index<active.ids.length-1?button('Próxima questão','next',undefined,'primary'):exam?button(review?'Voltar ao resultado':'Finalizar simulado',review?'view':'finish-exam',review?'exam-result':undefined,'primary'):button('Ver desempenho','view','progress','primary')}</div></div></section>`;}
  function emptyState(){const marked=state.practice.filter==='marked';return `<section class="empty-state">${icon(marked?'bookmark':'check')}<h2>${marked?'Nenhuma questão marcada nesta área':'Nenhum erro para revisar nesta área'}</h2><p>${marked?'Use o marcador ao lado de uma questão para voltar a ela mais tarde.':'As respostas incorretas aparecem aqui depois de serem conferidas no treino.'}</p>${button('Ver todas as questões','filter','all','primary')}</section>`;}
  function practiceView(){const a=state.practice,s=core.summarize(practiceDomain(),a.answers);return `${heading('Prática de questões',a.domain<0?'Transforme cada resposta em um conceito aprendido.':domains[a.domain]+' · 10 questões para praticar.',true)}${statsBoxes(s)}<div class="question-filter" role="group" aria-label="Filtrar questões">${[['all','Todas as questões'],['wrong','Revisar erros'],['marked','Marcadas']].map(([key,label])=>`<button class="filter-btn ${a.filter===key?'active':''}" data-action="filter" data-value="${key}" aria-pressed="${a.filter===key}">${label}</button>`).join('')}<button class="filter-btn reset-filter" data-action="reset-practice">${icon('refresh')} Reiniciar treino</button></div>${a.ids.length?`<div class="study-grid">${questionPanel(a)}<aside class="study-aside">${questionMap(a)}<section class="right-card tip-card"><span class="tip-icon">${icon('bulb')}</span><h2>Entenda o porquê</h2><p>No treino, confira a explicação após cada resposta. No simulado, reserve a revisão para o final.</p></section></aside></div>`:emptyState()}`;}
  function domainReport(answers,submitted=false){return `<div class="report-domains">${domains.map((domain,i)=>{const s=core.summarize(questions.filter(q=>q.domain===i),answers,submitted);return `<div class="domain-row"><span>${domain}</span><div class="progress-track" role="progressbar" aria-label="Acerto em ${domain}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${s.accuracy||0}"><div class="progress-fill" style="width:${s.accuracy||0}%"></div></div><span class="score">${s.correct}/${s.evaluated}${s.evaluated?' · '+s.accuracy+'%':' · não iniciado'}</span></div>`;}).join('')}</div>`;}
  function progressView(){const s=core.summarize(questions,state.practice.answers),wrong=questions.filter(q=>state.practice.answers[q.id]?.checked&&state.practice.answers[q.id].selected!==q.answer);return `${heading('Meu desempenho','Acompanhe sua prática por área de conhecimento.')}${statsBoxes(s)}<section class="report-card"><h2>Onde concentrar sua próxima revisão</h2><p>Considera a última resposta conferida de cada questão nesta sessão de treino.</p>${domainReport(state.practice.answers)}<div class="report-actions">${button('Continuar treino','view','practice','primary')}${button('Revisar erros'+(wrong.length?' ('+wrong.length+')':''),'review-wrong',undefined,'',!wrong.length)}${button('Fazer simulado','exam-open')}</div></section>${state.exam?.submitted?`<section class="right-card" style="margin-top:20px"><h2>Simulado desta sessão</h2><p>${core.summarize(questions,state.exam.answers,true).correct} acertos de 50 questões. O resultado do simulado fica separado do treino.</p>${button('Ver resultado do simulado','view','exam-result')}</section>`:''}<div class="note-panel"><strong>Uma medida de prática.</strong> O percentual ajuda a orientar sua revisão. Não equivale à pontuação oficial da Microsoft nem indica aprovação no exame. O rascunho é salvo apenas nesta aba e se encerra ao fechá-la.</div>`;}
  function examIntro(){const exists=state.exam;return `${heading('Simulado completo','Teste seus conhecimentos antes de consultar as explicações.',true)}<section class="report-card exam-intro"><div><p class="eyebrow">Cinco áreas · Uma sessão</p><h2>Coloque seus conceitos à prova.</h2><p>Responda às 50 questões, marque as que deseja revisar e navegue pelo mapa. As respostas e as explicações aparecem quando você finalizar.</p><div class="exam-facts"><span>50 questões</span><span>Uma resposta por questão</span><span>Sem limite de tempo</span></div><div class="report-actions">${exists?button(exists.submitted?'Ver último resultado':'Continuar simulado','view',exists.submitted?'exam-result':'exam','primary'):button('Começar simulado','start-exam',undefined,'primary')}${exists?button('Novo simulado','start-exam'):''}</div></div><div class="exam-number">50<small>questões para conectar os conceitos</small></div></section><div class="note-panel">Questões e alternativas são embaralhadas. Há 10 questões em cada área, seguindo a metodologia do material. Essa distribuição não reproduz os pesos oficiais do exame.</div>`;}
  function examView(review=false){const active=state.exam;if(!active)return examIntro();const s=core.summarize(questions,active.answers,review);return `${heading(review?'Revisão do simulado':'Simulado em andamento',review?'Confira as respostas e o conceito por trás de cada decisão.':'Responda no seu ritmo. A correção aparece ao finalizar.',true)}${review?`<div class="question-filter">${button('Voltar ao resultado','view','exam-result')}</div>`:statsBoxes(s,true)}<div class="study-grid">${questionPanel(active,review)}<aside class="study-aside">${questionMap(active,review)}<section class="right-card tip-card"><span class="tip-icon">${icon('bookmark')}</span><h2>${review?'Revise o conceito':'Está em dúvida?'}</h2><p>${review?'Compare sua escolha com a resposta e consulte a documentação para aprofundar o tema.':'Marque a questão e continue. Volte a ela pelo mapa antes de finalizar o simulado.'}</p></section></aside></div>`;}
  function examResult(){if(!state.exam?.submitted)return examIntro();const s=core.summarize(questions,state.exam.answers,true),missed=list(state.exam.ids).filter(q=>state.exam.answers[q.id]?.selected!==q.answer);return `<div class="result-heading"><p class="eyebrow">Simulado concluído</p><p class="result-score">${s.accuracy}%</p><h1 tabindex="-1">Cada revisão é um passo adiante.</h1><p>${s.correct} ${s.correct===1?'acerto':'acertos'} em 50 questões · ${s.wrong} incorretas · ${s.unanswered} em branco</p></div><section class="report-card"><h2>Seu resultado por área</h2><p>Questões em branco contam como não acertadas. O percentual representa apenas este simulado.</p>${domainReport(state.exam.answers,true)}<div class="report-actions">${button('Revisar todas as questões','exam-review',0,'primary')}${button('Novo simulado','start-exam')}${button('Voltar ao treino','view','practice')}</div>${missed.length?`<div class="review-list"><h2 style="margin-top:15px">Conceitos para revisar</h2>${missed.map(q=>`<button class="review-item" data-action="exam-review" data-value="${state.exam.ids.indexOf(q.id)}"><span class="review-num">${state.exam.ids.indexOf(q.id)+1}</span><span>${escape(q.concept)}<small>${domains[q.domain]}</small></span><span class="review-status">${Number.isInteger(state.exam.answers[q.id]?.selected)?'Incorreta':'Em branco'}</span></button>`).join('')}</div>`:'<div class="note-panel">Você acertou todas as questões desta sessão. Use os links das explicações para aprofundar os conceitos e complementar a prática com os objetivos oficiais.</div>'}</section>`;}
  function materialsView(){return `${heading('Materiais de estudo','Os arquivos que deram origem ao seu espaço de prática.')}<div class="materials-grid"><article class="material">${icon('file')}<h2>Simulado de referência</h2><p>O PDF original contém as 50 questões e o gabarito. O aplicativo mantém a relação com os temas e ajusta enunciados que precisavam de maior precisão.</p><a class="btn" href="materiais/simulado-original.pdf" target="_blank" rel="noopener noreferrer">Abrir PDF original ${icon('link')}</a></article><article class="material">${icon('book')}<h2>Metodologia de criação</h2><p>Critérios de elaboração, divisão de 10 questões por área e orientações para estudar os conceitos, além de memorizar respostas.</p><a class="btn" href="materiais/metodologia.md" download="Metodologia_Criacao_Questoes_AZ104.md">Baixar metodologia</a></article><article class="material">${icon('target')}<h2>Objetivos oficiais do AZ-104</h2><p>Consulte os tópicos e os pesos de cada área no guia da Microsoft. Este banco de 50 questões cobre os temas dos arquivos e não todo o programa do exame.</p><a class="btn" href="https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-104" target="_blank" rel="noopener noreferrer">Abrir guia oficial ${icon('link')}</a></article><article class="material">${icon('bulb')}<h2>Explicações com referências</h2><p>Cada questão tem uma explicação e um link para a documentação correspondente no Microsoft Learn. Referências consultadas em 07/10/2026.</p>${button('Voltar à prática','view','practice')}</article></div><div class="note-panel"><strong>Sobre o conteúdo.</strong> Os arquivos originais foram preservados. As letras variam no aplicativo porque as alternativas são embaralhadas. As questões 21 e 22 tratam de restrições de Azure Disk Encryption em ambientes existentes; a Microsoft prevê sua retirada em 15/09/2028 e recomenda encryption at host para novas VMs. <a href="https://learn.microsoft.com/en-us/azure/virtual-machines/windows/disk-encryption-windows" target="_blank" rel="noopener noreferrer">Ver orientação da Microsoft</a>.</div>`;}
  function render(focusSelector){const views={practice:practiceView,progress:progressView,materials:materialsView,'exam-intro':examIntro,exam:()=>examView(false),'exam-result':examResult,'exam-review':()=>examView(true)};document.getElementById('app').innerHTML=shell((views[state.view]||practiceView)());document.querySelector('.sidebar').inert=window.innerWidth<=760&&!menuOpen;document.querySelector('.sidebar').insertAdjacentHTML('afterbegin',`<button class="sidebar-close" data-action="menu" aria-label="Fechar menu de navegação">${icon('cross')}</button>`);save();if(focusSelector)document.querySelector(focusSelector)?.focus({preventScroll:true});}
  function navigate(view){if(['exam','exam-review','exam-result'].includes(view)&&!state.exam)view='exam-intro';state.view=view;menuOpen=false;render('h1');window.scrollTo(0,0);}
  function setFilter(filter){if(!['all','wrong','marked'].includes(filter))return;state.practice.filter=filter;state.practice.ids=practiceDomain().filter(q=>filter==='all'||(filter==='marked'?state.marked.includes(q.id):state.practice.answers[q.id]?.checked&&state.practice.answers[q.id].selected!==q.answer)).map(q=>q.id);state.practice.index=0;state.view='practice';menuOpen=false;render('h1');}
  function setDomain(domain){if(!Number.isInteger(domain)||domain< -1||domain>4)return;state.practice.domain=domain;setFilter('all');window.scrollTo(0,0);}
  function selectOption(index){const q=current(),active=session();if(!q||!Number.isInteger(index)||index<0||index>3)throw new Error('Alternativa inválida.');const a=getAnswer(q,active);if(state.view==='exam-review'||(state.view==='practice'&&a.checked)||(active===state.exam&&active.submitted))throw new Error('A resposta já foi conferida.');a.selected=index;render(`[data-action="select"][data-value="${index}"]`);}
  function checkAnswer(){if(state.view!=='practice')throw new Error('A correção individual está disponível no treino.');const q=current();if(!q)throw new Error('Nenhuma questão selecionada.');const a=getAnswer(q);if(a.selected===null)throw new Error('Selecione uma alternativa.');a.checked=true;render('#feedback-title');}
  function moveTo(index){const active=session();if(!active||!Number.isInteger(index)||index<0||index>=active.ids.length)return;active.index=index;render('.question-text');if(window.innerWidth<1050)document.querySelector('.question-card')?.scrollIntoView({block:'start'});}
  function beginExam(){state.exam={ids:core.shuffle(questions.map(q=>q.id)),index:0,answers:{},submitted:false};navigate('exam');}
  function finishExam(){if(!state.exam||state.exam.submitted)return;const n=core.summarize(questions,state.exam.answers).unanswered;openDialog('Finalizar simulado?',n?`${n} ${n===1?'questão ficou':'questões ficaram'} em branco. Elas contarão como não acertadas. Você poderá consultar todas as explicações no resultado.`:'Suas 50 respostas serão corrigidas. Você poderá revisar as explicações no resultado.','Finalizar e corrigir',()=>{state.exam.submitted=true;navigate('exam-result');});}
  function toast(message){document.querySelector('.toast')?.remove();const element=document.createElement('div');element.className='toast';element.setAttribute('role','status');element.textContent=message;document.body.append(element);clearTimeout(toastTimer);toastTimer=setTimeout(()=>element.remove(),3000);}
  function openDialog(title,text,label,action){dialogReturnFocus=document.activeElement;dialogAction=action;const element=document.createElement('div');element.className='dialog-backdrop';element.id='study-dialog';element.innerHTML=`<section class="dialog-box" role="dialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-description"><h2 id="dialog-title">${escape(title)}</h2><p id="dialog-description">${escape(text)}</p><div class="dialog-buttons">${button('Voltar','dialog-cancel')}${button(escape(label),'dialog-confirm',undefined,'primary')}</div></section>`;document.body.append(element);element.querySelector('[data-action="dialog-cancel"]').focus();document.querySelector('.shell').inert=true;}
  function closeDialog(){document.getElementById('study-dialog')?.remove();const shellElement=document.querySelector('.shell');if(shellElement)shellElement.inert=false;dialogAction=null;if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();}
  function runAction(action,value){switch(action){
    case 'view':if(['practice','progress','materials','exam','exam-result','exam-intro'].includes(value))navigate(value);break;
    case 'domain':setDomain(Number(value));break;case 'filter':setFilter(value);break;case 'select':selectOption(Number(value));break;case 'check':checkAnswer();break;
    case 'next':moveTo(session().index+1);break;case 'previous':moveTo(session().index-1);break;case 'jump':moveTo(Number(value));break;
    case 'bookmark':{const q=current();if(!q)break;if(state.marked.includes(q.id))state.marked=state.marked.filter(id=>id!==q.id);else state.marked.push(q.id);render('[data-action="bookmark"]');toast(state.marked.includes(q.id)?'Questão marcada para revisão.':'Marcação removida.');break;}
    case 'retry':{const q=current();if(q&&state.view==='practice'){state.practice.answers[q.id]=core.newAnswer();render('[data-action="select"]');}break;}
    case 'review-wrong':state.practice.domain=-1;setFilter('wrong');break;
    case 'reset-practice':openDialog('Reiniciar este treino?','As respostas do treino nesta área serão reiniciadas. As marcações e o simulado desta sessão serão mantidos.','Reiniciar treino',()=>{practiceDomain().forEach(q=>delete state.practice.answers[q.id]);setFilter('all');});break;
    case 'exam-open':navigate(state.exam?state.exam.submitted?'exam-result':'exam':'exam-intro');break;
    case 'start-exam':if(state.exam)openDialog('Começar novo simulado?','O simulado atual será substituído. A prática por tema será mantida.','Começar novo',beginExam);else beginExam();break;
    case 'finish-exam':finishExam();break;case 'exam-review':if(state.exam?.submitted){state.exam.index=Number(value)||0;navigate('exam-review');}break;
    case 'menu':menuOpen=!menuOpen;render('[data-action="menu"]');break;case 'dialog-cancel':closeDialog();break;
    case 'dialog-confirm':{const actionToRun=dialogAction;closeDialog();actionToRun?.();break;}
  }}
  document.addEventListener('click',event=>{const control=event.target.closest('[data-action]');if(!control||control.disabled)return;event.preventDefault();try{runAction(control.dataset.action,control.dataset.value);}catch(error){toast(error.message||'Não foi possível executar esta ação.');}});
  document.addEventListener('keydown',event=>{const dialog=document.getElementById('study-dialog');if(dialog){if(event.key==='Escape'){event.preventDefault();closeDialog();return;}if(event.key==='Tab'){const controls=[...dialog.querySelectorAll('button')],first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}return;}if(event.key==='Escape'&&menuOpen){menuOpen=false;render('[data-action="menu"]');return;}const choice=event.target.closest('[data-action="select"]');if(choice&&!choice.disabled&&['ArrowDown','ArrowRight','ArrowUp','ArrowLeft'].includes(event.key)){event.preventDefault();const a=getAnswer(current()),position=a.order.indexOf(Number(choice.dataset.value)),delta=['ArrowDown','ArrowRight'].includes(event.key)?1:-1;selectOption(a.order[(position+delta+4)%4]);}});
  function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();
    const readState=()=>{const q=current(),active=session(),a=q&&active?getAnswer(q,active):null,revealed=state.view==='exam-review'||(state.view==='practice'&&a?.checked);return {view:state.view,question:q?{id:q.id,domain:domains[q.domain],prompt:q.prompt,options:a.order.map((index,i)=>({letter:'ABCD'[i],text:q.options[index]})),selected:a.selected===null?null:'ABCD'[a.order.indexOf(a.selected)],...(revealed?{correctAnswer:'ABCD'[a.order.indexOf(q.answer)],explanation:q.explanation}:{})}:null};};
    const definitions=[
      {name:'read_study_state',title:'Ler questão atual',description:'Lê a questão e as alternativas visíveis. A resposta correta só aparece após a correção.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw new Error('Esperado um objeto vazio.');return readState();}},
      {name:'navigate_practice_area',title:'Abrir área de treino',description:'Abre a prática na área especificada, mantendo as respostas da sessão. Use -1 para todas ou 0 a 4 para as cinco áreas.',inputSchema:{type:'object',properties:{domain:{type:'integer',minimum:-1,maximum:4}},required:['domain'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!Number.isInteger(input.domain)||input.domain< -1||input.domain>4)throw new Error('Área inválida.');setDomain(input.domain);return readState();}},
      {name:'stage_question_answer',title:'Selecionar alternativa',description:'Seleciona A, B, C ou D na questão atual, sem corrigir nem finalizar o simulado.',inputSchema:{type:'object',properties:{letter:{type:'string',enum:['A','B','C','D']}},required:['letter'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['A','B','C','D'].includes(input.letter))throw new Error('Alternativa inválida.');const q=current();if(!q)throw new Error('Abra uma questão primeiro.');selectOption(getAnswer(q).order['ABCD'.indexOf(input.letter)]);return readState();}},
      {name:'check_practice_answer',title:'Corrigir resposta de treino',description:'Corrige a alternativa selecionada no modo treino e mostra a explicação. Não finaliza o simulado.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw new Error('Esperado um objeto vazio.');checkAnswer();return readState();}}
    ];for(const tool of definitions)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch(_){}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
  let previousMobile=window.innerWidth<=760;
  window.addEventListener('resize',()=>{const mobile=window.innerWidth<=760;if(previousMobile!==mobile){previousMobile=mobile;document.querySelector('.sidebar').inert=mobile&&!menuOpen;}});
  render();registerTools();
})();
